  transition: transform var(--motion-duration-slow)
    cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform;
}

.digitStack > span {
  flex: 0 0 1lh;
  height: 1lh;
}

@media (prefers-reduced-motion: reduce) {
  .digitStack {
    transition: none;
  }
}

